function R=w2e_run_scalar_row(E)
%W2E_RUN_SCALAR_ROW Scalar-only CSV projection of a run summary.
fn={'Index','Method','Status','Completed','FailureClass','DomainExit','NumericalFailure','ErrorId','ErrorMessage','rhoB','InitialVB_over_rhoB', ...
'IntegrationWall_s','OutputWall_s','PosRMSFull_m','PosPeakFull_m','PosRMSLate_m','PosPeakLate_m','LateWindErrorMax_mps','GovInterventionPct','InterventionSamples', ...
'MeanCorrectionNorm','MedianCorrectionNorm','MaxCorrectionNorm','MeanObjective','MedianObjective','MaxObjective','MeanObjectiveActive','IntegratedObjective_s','MinScalarLambda', ...
'MinAppliedPhi','MaxNormalizedPhiViolation','MaxVB_over_rhoB','MinBackupMargin','MaxAttitudeTube_deg','ActualVmin_mps','ActualVmax_mps','ActualMaxAbsGamma_deg','ActualAlphaMin_deg','ActualAlphaMax_deg','ActualMaxAbsBeta_deg','MinKappa','ActualTmin_N','ActualTmax_N','MaxThrustRate_Nps', ...
'Delta1Max_deg','Delta2Max_deg','Delta3Max_deg','DeltaRate1Max_degps','DeltaRate2Max_degps','DeltaRate3Max_degps','AllocatorActiveSamples','MaxMomentResidual_Nm','LateMomentResidual_Nm','MaxSurfaceForce_N','MaxSlidingIdentityResidual','MaxWindKinematicResidual','MaxQNormError','MaxQrNormError', ...
'ReferenceAffinePass','ReferenceNormalizedPass','BackupSetPass','AirspeedPass','GammaPass','AlphaPass','SurfaceBoxPass','SurfaceRatePass','ThrustBoxPass','ThrustRatePass','QuaternionPass','KappaPositivePass','ActuatorBoxPass','HardFeasible','QPKKTGatePass','CorePass','AttitudeTubePass','BetaTubePass','KappaCertPass','CertifiedDomain', ...
'QPEnumerationFallbackSamples','QPFeasiblePathSamples','QPSingleHalfspaceSamples','QPPrimalActiveSetSamples','QPEnumerationSamples','QPMaxPrimal','QPMaxStationarity','QPMaxDualViolation','QPMaxComplementarity','NonbackupPhysicalRoleSamples','ThrustRoleSamples','TminRoleSamples','TmaxRoleSamples','BackupRoleSamples'};
R=struct();for k=1:numel(fn),R.(fn{k})=E.(fn{k});end;R.LateErLinfN_m=E.LateErLinf_m(1);R.LateErLinfE_m=E.LateErLinf_m(2);R.LateErLinfD_m=E.LateErLinf_m(3);
end
